  "Ta dépense : les crédits sortis de ta poche à l'achat, armes payées pour un coéquipier comprises ; équipement : ce que tu tiens à la fin de l'achat, capacités comprises ; crédits gardés : ce qui te reste après l'achat ; dégâts pour 1\u202f000 crédits de cet équipement ; tes lobbys : les autres joueurs de tes parties, sur les mêmes parties. Ta dépense ne compte que les manches vérifiées, où tes crédits, par les règles du jeu, redonnent la dépense que Riot te compte (ou partent d'un départ fixé, au pistolet et en prolongation), dans les parties qui ont la dépense de Riot par manche.": "Your spend: the credits out of your pocket at the buy, weapons bought for a teammate included; loadout: what you hold at the end of the buy phase, abilities included; credits saved: what you have left after buying; damage per 1,000 credits of that loadout; your lobbies: the other players in your matches, over the same matches. Your spend only counts verified rounds, where your credits, by the game's rules, match the spend Riot counts for you (or start from a fixed amount, on pistol rounds and in overtime), in matches that have Riot's per-round spend.",
