  // prix-reference.ts — les preuves des prix confirmés (« Prix confirmé : … », Source du prix)
  "dbltap.com et earlygame.com (Vandal 2 675, Karambit 5 350, cartes 375) ; upcomer.com (« Individual items … available separate », mêmes montants)": "dbltap.com and earlygame.com (Vandal 2,675, Karambit 5,350, cards 375); upcomer.com (“Individual items … available separate”, same amounts)",
  "ginx.tv (liste des prix : Phantom 2 675, couteau papillon 5 350, carte, porte-bonheur, tag) ; turbosmurfs.gg et wiki.playvalorant.com (Weird Gloop) : 2 675, 5 350, 375, 475, 325": "ginx.tv (price list: Phantom 2,675, butterfly knife 5,350, card, Gun Buddy, Spray); turbosmurfs.gg and wiki.playvalorant.com (Weird Gloop): 2,675, 5,350, 375, 475, 325",
  "news.codashop.com (Vandal 2 675, mêlée 5 350, carte 375, tag 325) ; turbosmurfs.gg (mêmes montants)": "news.codashop.com (Vandal 2,675, melee 5,350, card 375, Spray 325); turbosmurfs.gg (same amounts)",
  "thespike.gg (« option to get items separately » : Phantom 2 675, mêlée 5 350, carte 375, porte-bonheur 475, tag 325) ; turbosmurfs.gg et tracker.gg (mêmes montants)": "thespike.gg (“option to get items separately”: Phantom 2,675, melee 5,350, card 375, Gun Buddy 475, Spray 325); turbosmurfs.gg and tracker.gg (same amounts)",
  "gamingamigos.com et turbosmurfs.gg (couteau papillon 5 350, carte 375, porte-bonheur 475, tag 325, flex 975) ; wiki.playvalorant.com (mêmes montants)": "gamingamigos.com and turbosmurfs.gg (butterfly knife 5,350, card 375, Gun Buddy 475, Spray 325, Flex 975); wiki.playvalorant.com (same amounts)",
  "2 675 ou 2 676 VP selon les sources relevées en 8.13 : 2 675 retenu sur confirmation de l'utilisateur (2026-11-10), prix de toutes les armes Champions depuis 2021": "2,675 or 2,676 VP depending on the sources found in 8.13: 2,675 kept on the user's confirmation (2026-11-10), the price of every Champions weapon since 2021",
  "playvalorant.com (officiel : « Pack collector d'Arcane », 2 380 VP, « ne peuvent être achetés que via ce pack complet » : Sheriff (Arcane), porte-bonheur Singeries)": "playvalorant.com (official: “Arcane Collector's Pack”, 2,380 VP, “can only be purchased through this full pack”: Sheriff (Arcane), Gun Buddy)",
  "news.codashop.com et thespike.gg (pack complet 5 925 VP ; Vandal 2 175, Gantelets 4 350, carte 375, porte-bonheur 475, tag 325, vente à l'unité non dite) ; playvalorant.com (officiel : contenu)": "news.codashop.com and thespike.gg (full pack 5,925 VP; Vandal 2,175, Gauntlets 4,350, card 375, Gun Buddy 475, Spray 325, single-item sale not stated); playvalorant.com (official: contents)",
  "valorantesports.com (officiel : capsule VCT LOCK//IN, objets « nur als Gesamtpaket verfügbar ») ; ginx.tv et wiki.playvalorant.com : 5 440 VP": "valorantesports.com (official: VCT LOCK//IN capsule, items “nur als Gesamtpaket verfügbar”); ginx.tv and wiki.playvalorant.com: 5,440 VP",
  "valorantesports.com (officiel : contenu, Karambit, 4 cartes, 4 porte-bonheur) ; 5 850 VP : wiki.playvalorant.com, strafe.com, outlookindia.com": "valorantesports.com (official: contents, Karambit, 4 cards, 4 Gun Buddies); 5,850 VP: wiki.playvalorant.com, strafe.com, outlookindia.com",
  "thespike.gg (4 710 VP, « wasn't able to be purchased individually ») ; wiki.playvalorant.com (4 710, vente à l'unité impossible) ; tracker.gg, thenerdstash.com (contenu : éventail, cartes et tags Huang et Feng, titres Flex et Pyromien)": "thespike.gg (4,710 VP, “wasn't able to be purchased individually”); wiki.playvalorant.com (4,710, no single-item sale); tracker.gg, thenerdstash.com (contents: fan, Huang and Feng cards and Sprays, Flex and Pyromien titles)",
  "gfinityesports.com (3 915 VP, couteau impossible à acheter seul ; couteau, porte-bonheur, carte, tag) ; wiki.playvalorant.com et thespike.gg (même prix ; titre)": "gfinityesports.com (3,915 VP, knife not sold on its own; knife, Gun Buddy, card, Spray); wiki.playvalorant.com and thespike.gg (same price; title)",
  "thespike.gg et gameriv.com (« Each VCT Team Capsule costs 2340 VP », « you can't purchase any single item within the Capsules ») ; wiki.playvalorant.com (même prix)": "thespike.gg and gameriv.com (“Each VCT Team Capsule costs 2340 VP”, “you can't purchase any single item within the Capsules”); wiki.playvalorant.com (same price)",
  "ginx.tv (« Each team capsule will cost 2320 VP ») et win.gg (« The total bundle costs 2,320 Valorant Points ») ; vente à l'unité contradictoire (win.gg oui, wiki non) : « vendu dans », sans « seulement »": "ginx.tv (“Each team capsule will cost 2320 VP”) and win.gg (“The total bundle costs 2,320 Valorant Points”); conflicting on single-item sale (win.gg yes, wiki no): “sold in”, without “only”",
  "dotesports.com (capsule VCT CN 2024 : Classic aux couleurs de l'équipe et porte-bonheur, « about 1,880 VP ») ; esports.gg (capsules chinoises « at discounted price ») : une seule source du montant, admise par l'utilisateur (2026-11-10)": "dotesports.com (VCT CN 2024 capsule: Classic in the team's colors and Gun Buddy, “about 1,880 VP”); esports.gg (Chinese capsules “at discounted price”): a single source for the amount, accepted by the user (2026-11-10)",
  "esports.gg (les équipes de VCT China reçoivent en 2025 la capsule complète, après la version réduite de 2024) ; tracker.gg (capsules 2025 à 2 320 VP, EDG parmi les équipes) ; ginx.tv (2 320 VP par capsule) : admis par l'utilisateur (2026-11-10)": "esports.gg (VCT China teams get the full capsule in 2025, after the reduced 2024 version); tracker.gg (2025 capsules at 2,320 VP, EDG among the teams); ginx.tv (2,320 VP per capsule): accepted by the user (2026-11-10)",
  "valorant-api (cartes « Carte maîtrise de … », dossier Bloomline) ; thespike.gg et beebom.com : la carte de maîtrise, récompense du niveau 30 de la maîtrise d'agent": "valorant-api (“Mastery card” cards, Bloomline folder); thespike.gg and beebom.com: the mastery card, the level 30 reward of Agent Mastery",
  "thespike.gg (maîtrise de Hush, niveau 15, « Brainwaves Bandit (8,000 KC) ») ; wiki.playvalorant.com et beatcopgame.com (8 000 crédits Kingdom)": "thespike.gg (Hush mastery, level 15, “Brainwaves Bandit (8,000 KC)”); wiki.playvalorant.com and beatcopgame.com (8,000 Kingdom Credits)",
  "valorant-api (chemins d'asset « Premier… ») ; ggrecon.com, dbltap.com, afkgaming.com : titres, porte-bonheur et cartes de Premier gagnés en jouant et en remportant les phases": "valorant-api (“Premier…” asset paths); ggrecon.com, dbltap.com, afkgaming.com: Premier titles, Gun Buddies and cards earned by playing and winning stages",
  "valorant-api (porte-bonheur « Buddies/Rank… ») ; playvalorant.com (officiel, notes de version 10.08 : porte-bonheur de classement selon le rang atteint) ; win.gg, upcomer.com (porte-bonheur d'épisode)": "valorant-api (“Buddies/Rank…” Gun Buddies); playvalorant.com (official, patch notes 10.08: ranked Gun Buddies by rank reached); win.gg, upcomer.com (Episode Gun Buddies)",
  "valorant-api (chemins d'asset des récompenses de l'esport : Pick'Ems, drops, Shotcall, vainqueurs, carte Champions 2021 « Viewer ») ; valorantesports.com (officiel : porte-bonheur et tag VCT en drops Twitch, carte Champions 2021 offerte à tous les comptes actifs) ; sheepesports.com, esportnow.gg, oneesports.gg (Pick'Ems, drops, Shotcall)": "valorant-api (esports reward asset paths: Pick'Ems, drops, Shotcall, winners, Champions 2021 “Viewer” card); valorantesports.com (official: VCT Gun Buddy and Spray as Twitch drops, Champions 2021 card given to every active account); sheepesports.com, esportnow.gg, oneesports.gg (Pick'Ems, drops, Shotcall)",
